package dev.veltraph.client.capture.tool;
import com.google.gson.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class SelectedToolCaptureSchemaTest {
 private JsonObject data(String uuid){return JsonParser.parseString("{\"minecraft:custom_data\":{\"ExtraAttributes\":{\"id\":\"MELON_DICER_3\",\"uuid\":\""+uuid+"\",\"farmed_cultivating\":1234,\"unknown\":\"SECRET_SENTINEL\",\"owner\":\"ACCOUNT_SENTINEL\"}},\"minecraft:lore\":[\"PRIVATE_LORE_SENTINEL\"]}").getAsJsonObject();}
 private byte[] salt(int value){byte[] a=new byte[32];Arrays.fill(a,(byte)value);return a;}
 @Test void approvedIdsCountersAndFieldTypesWithoutRawValues(){var x=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,data("12345678-1234-1234-1234-123456789abc"),List.of("§aCounter: 1,234 crops","private lore"),salt(1));String s=x.toString();assertTrue(s.contains("MELON_DICER_3"));assertTrue(s.contains("1234"));assertTrue(s.contains("unknown"));assertFalse(s.contains("SECRET_SENTINEL"));assertFalse(s.contains("ACCOUNT_SENTINEL"));assertFalse(s.contains("PRIVATE_LORE_SENTINEL"));assertFalse(s.contains("12345678-1234"));assertEquals(1,x.getAsJsonArray("recognizedNumericLoreCounters").size());}
 @Test void uuidDigestStableWithinSessionButDifferentAcrossSalts(){var d=data("12345678-1234-1234-1234-123456789abc");var a=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of(),salt(1));var b=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of(),salt(1));var c=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of(),salt(2));assertEquals(a,b);assertNotEquals(a.get("sessionSaltedToolUuidDigests"),c.get("sessionSaltedToolUuidDigests"));}
 @Test void arbitraryUuidPathsAndUnknownNumbersAreNotExported(){var d=JsonParser.parseString("{\"minecraft:custom_data\":{\"owner_uuid\":\"12345678-1234-1234-1234-123456789abc\",\"other\":8675309,\"ExtraAttributes\":{\"farmed_cultivating\":\"123\",\"mined_crops\":-1}}}").getAsJsonObject();var x=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of("Counter: -3","Cultivating: 9999999999999999999999999999"),salt(1));assertTrue(x.getAsJsonObject("recognizedNumericCustomDataCounters").isEmpty());assertTrue(x.getAsJsonArray("recognizedNumericLoreCounters").isEmpty());assertFalse(x.toString().contains("8675309"));assertTrue(x.getAsJsonObject("sessionSaltedToolUuidDigests").isEmpty());}
 @Test void nativeCustomDataDepthBoundIsActuallyReached(){var d=new JsonObject();var custom=new JsonObject();d.add("minecraft:custom_data",custom);var child=custom;for(int i=0;i<10;i++){var next=new JsonObject();child.add("level",next);child=next;}child.addProperty("secret","SECRET_DEPTH_SENTINEL");var x=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of(),salt(1));assertTrue(x.get("schemaBoundReached").getAsBoolean());assertTrue(x.getAsJsonArray("componentFields").size()>1);assertTrue(x.getAsJsonArray("componentFields").size()<20);assertFalse(x.toString().contains("SECRET_DEPTH_SENTINEL"));}
 @Test void nativeCustomDataFieldBoundIsActuallyReached(){var d=new JsonObject();var custom=new JsonObject();d.add("minecraft:custom_data",custom);for(int i=0;i<600;i++)custom.addProperty("field"+i,"SECRET_FIELD_SENTINEL");var x=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of(),salt(1));assertTrue(x.get("schemaBoundReached").getAsBoolean());assertEquals(512,x.getAsJsonArray("componentFields").size());assertFalse(x.toString().contains("SECRET_FIELD_SENTINEL"));}
 @Test void unsafeFieldNamesDoNotLeakRawUuidOrArbitraryText(){var d=new JsonObject();d.addProperty("12345678-1234-1234-1234-123456789abc","secret");d.addProperty("private user@example.com","secret");var x=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of(),salt(1));assertTrue(x.get("schemaBoundReached").getAsBoolean());assertFalse(x.toString().contains("12345678"));assertFalse(x.toString().contains("example.com"));}
 @Test void invalidNativeIdSlotOrSaltDenied(){assertThrows(IllegalArgumentException.class,()->SelectedToolCaptureSchema.encode("bad id",0,new JsonObject(),List.of(),salt(1)));assertThrows(IllegalArgumentException.class,()->SelectedToolCaptureSchema.encode("minecraft:stone",9,new JsonObject(),List.of(),salt(1)));assertThrows(IllegalArgumentException.class,()->SelectedToolCaptureSchema.encode("minecraft:stone",0,new JsonObject(),List.of(),new byte[2]));}
 @Test void flatDotBracketUnicodeAndControlKeysCannotSpoofApprovedNestedPaths(){var d=new JsonObject();var custom=new JsonObject();custom.addProperty("ExtraAttributes.id","SECRET_UNKNOWN_UPPERCASE");custom.addProperty("ExtraAttributes.uuid","12345678-1234-1234-1234-123456789abc");custom.addProperty("ExtraAttributes[farmed_cultivating]",123);custom.addProperty("ExtraAttributes\n.id","SECRET_UNKNOWN_UPPERCASE");custom.addProperty("ExtrаAttributes.id","SECRET_UNKNOWN_UPPERCASE");d.add("minecraft:custom_data",custom);var x=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of(),salt(1));assertTrue(x.getAsJsonObject("allowlistedServerItemIds").isEmpty());assertTrue(x.getAsJsonObject("recognizedNumericCustomDataCounters").isEmpty());assertTrue(x.getAsJsonObject("sessionSaltedToolUuidDigests").isEmpty());assertFalse(x.toString().contains("SECRET_UNKNOWN_UPPERCASE"));}
 @Test void compactUuidAndPrefixedUuidFieldNamesAreNotExported(){var d=new JsonObject();var custom=new JsonObject();custom.addProperty("abcdefabcdefabcdefabcdefabcdefab","secret");custom.addProperty("owner_abcdefabcdefabcdefabcdefabcdefab","secret");d.add("minecraft:custom_data",custom);var x=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,d,List.of(),salt(1));assertTrue(x.get("schemaBoundReached").getAsBoolean());assertFalse(x.toString().contains("abcdefabcdef"));}
}
